/* @lc app=leetcode id=3703 lang=kotlin */ class Solution { fun removeSubstring(s: String, k: Int): String = s.fold(ArrayList<Pair<Char, Int>>()) { st, c -> (if (st.isNotEmpty() && st.last().first == c) st.set(st.size - 1, c to st.last().second + 1) else st.add(c to 1)).let { if (c == ')' && st.last().second == k && st.size >= 2 && st[st.size - 2].first == '(' && st[st.size - 2].second >= k) st.removeAt(st.size - 1).let { st.removeAt(st.size - 1).let { prev -> if (prev.second > k) st.add('(' to prev.second - k) } } }.let { st } }.joinToString("") { (c, n) -> c.toString().repeat(n) } }